import{_ as a,o as t,c as s,ag as n}from"./chunks/framework.DQQHyi2x.js";const u=JSON.parse('{"title":"Agent Teams","description":"","frontmatter":{},"headers":[],"relativePath":"features/agent-teams.md","filePath":"features/agent-teams.md"}'),o={name:"features/agent-teams.md"};function i(l,e,r,c,d,p){return t(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="agent-teams" tabindex="-1">Agent Teams <a class="header-anchor" href="#agent-teams" aria-label="Permalink to &quot;Agent Teams&quot;">​</a></h1><p>Agent Teams are saved rosters of local Codex and Claude Code sessions. Use them when the same group of repositories should be launched or reused together, such as a project team, DevOps team, or release validation team.</p><h2 id="what-a-team-contains" tabindex="-1">What A Team Contains <a class="header-anchor" href="#what-a-team-contains" aria-label="Permalink to &quot;What A Team Contains&quot;">​</a></h2><p>Each team has slots. A slot stores:</p><ul><li>provider</li><li>repository path</li><li>display name</li><li>role and charter</li><li>optional bootstrap prompt</li><li>launch mode and provider options</li><li>enabled or disabled state</li></ul><p>Agent Teams do not create a second messaging system. Once agents are launched or reused, use Agent Mail for messages, context requests, and handoffs.</p><h2 id="creating-teams" tabindex="-1">Creating Teams <a class="header-anchor" href="#creating-teams" aria-label="Permalink to &quot;Creating Teams&quot;">​</a></h2><p>You can create a team manually, import selected Agent Mail members, or snapshot currently visible Agent Bridge sessions.</p><p><code>From Mail</code> uses Agent Mail participants and copies their current role and charter into slot-specific values. This is a snapshot; editing a team slot does not update existing mail history.</p><p><code>From Bridge</code> uses live Agent Bridge tmux sessions. If multiple sessions are visible for the same repo, Claude Deck keeps each session as a separate slot so the resulting team can have distinct same-repo roles.</p><h2 id="launch-planning" tabindex="-1">Launch Planning <a class="header-anchor" href="#launch-planning" aria-label="Permalink to &quot;Launch Planning&quot;">​</a></h2><p>Before launch, Claude Deck computes a plan. The plan checks:</p><ul><li>provider availability</li><li>Agent Mail MCP/hooks readiness</li><li>live Agent Bridge tmux sessions that can be reused</li><li>disabled slots</li><li>provider launch option validity</li></ul><p>By default, launch only includes enabled slots and only reuses wakeable sessions observed through Agent Bridge. Connected non-tmux Agent Mail sessions can still communicate, but they are not reliable team launch/reuse targets.</p><h2 id="external-local-agents" tabindex="-1">External Local Agents <a class="header-anchor" href="#external-local-agents" aria-label="Permalink to &quot;External Local Agents&quot;">​</a></h2><p>Local external agents can use the JSON API:</p><ol><li><code>GET /api/v1/agent-teams/presets</code></li><li><code>POST /api/v1/agent-teams/presets/{preset_id}/plan-launch</code></li><li>inspect <code>items</code> and <code>plan_hash</code></li><li><code>POST /api/v1/agent-teams/presets/{preset_id}/launch</code></li></ol><p>Launch accepts a reviewed <code>confirm_plan_hash</code>, or <code>skip_plan_confirmation: true</code> for explicit single-step local automation. If a plan hash is stale, the API returns <code>409</code> with the updated plan.</p><p>After a launch, use the <a href="./external-agent-orchestration.html">External Agent Orchestration</a> Agent Mail API to discover registered participants, send context requests, create handoffs, and poll for answers.</p>',19)])])}const m=a(o,[["render",i]]);export{u as __pageData,m as default};
